#!/usr/bin/env python3
"""Tela TV FSJ aprovada: logotipo, início explícito e retorno ao término."""
from pathlib import Path
import sys,hashlib,datetime,shutil,os
EXPECTED_APP_SHA256='431321053c1831e4f21210dc9f0ff86b3405cd9b49813e75eff46cfa13fd6730'
REPLACEMENTS=[("$('player').addEventListener('ended',()=>{if(window.fsjWatchEnded?.())return;if(!projectedVideo||projectedVideo.institutional)return;$('videos').value='';const institutional=library.find(x=>x.institutional);project(institutional);if(institutional)$('player').play().catch(()=>{});document.dispatchEvent(new Event('fsj:projection-changed'));});", "$('player').addEventListener('ended',()=>{if(window.fsjWatchEnded?.())return;window.fsjTVHome?.();});"), ('project(institutional);if(institutional)player.play().catch(()=>{});applying=false;changed();}', 'project(institutional);applying=false;changed();}'), ("frame.src='https://www.youtube.com/embed/'+encodeURIComponent(video.youtube_id)+'?rel=0&autoplay=1';frame.hidden=false;", "if(window.fsjTVYoutube)window.fsjTVYoutube(video);else frame.src='https://www.youtube.com/embed/'+encodeURIComponent(video.youtube_id)+'?rel=0&autoplay=1';frame.hidden=false;")]
APPEND_JS='\nconst FSJ_TV_LOGO_SOURCE="data:image/png;base64,";\n/* FSJ_TV_POSTER_V1 */\n;(()=>{\n const stage=$(\'videoStage\'),player=$(\'player\');if(!stage||!player)return;\n const poster=document.createElement(\'div\');poster.id=\'fsjTVPoster\';\n const logo=document.createElement(\'img\');logo.src=FSJ_TV_LOGO_SOURCE;logo.alt=\'Fazenda São José\';\n const start=document.createElement(\'button\');start.id=\'fsjTVStart\';start.type=\'button\';start.textContent=\'▶ TV FSJ\';start.setAttribute(\'aria-label\',\'Iniciar vídeo institucional\');\n poster.append(logo,start);stage.prepend(poster);\n const youtubeHost=document.createElement(\'div\');youtubeHost.id=\'fsjTVYoutube\';youtubeHost.hidden=true;stage.prepend(youtubeHost);\n let youtubePlayer=null,youtubeGeneration=0,youtubeAPI=null;\n function clearYoutube(){youtubeGeneration++;if(youtubePlayer){try{youtubePlayer.destroy();}catch{}youtubePlayer=null;}youtubeHost.replaceChildren();youtubeHost.hidden=true;}\n function loadYoutubeAPI(){\n  if(window.YT?.Player)return Promise.resolve();if(youtubeAPI)return youtubeAPI;\n  youtubeAPI=new Promise((resolve,reject)=>{let done=false;const timeout=setTimeout(()=>{if(!done){done=true;reject(Error(\'YouTube indisponível. Verifique sua conexão com a internet.\'));}},15000);\n   const previous=window.onYouTubeIframeAPIReady;\n   window.onYouTubeIframeAPIReady=()=>{try{previous?.();}finally{if(!done){done=true;clearTimeout(timeout);resolve();}}};\n   const tag=document.createElement(\'script\');tag.src=\'https://www.youtube.com/iframe_api\';tag.onerror=()=>{if(!done){done=true;clearTimeout(timeout);reject(Error(\'Não foi possível carregar o YouTube.\'));}};document.head.append(tag);\n  }).catch(error=>{youtubeAPI=null;throw error;});return youtubeAPI;\n }\n window.fsjTVYoutube=video=>{\n  const generation=youtubeGeneration;youtubeHost.hidden=false;\n  loadYoutubeAPI().then(()=>{\n   if(generation!==youtubeGeneration||projectedVideo?.id!==video.id)return;\n   const mount=document.createElement(\'div\');youtubeHost.append(mount);\n   youtubePlayer=new YT.Player(mount,{videoId:video.youtube_id,width:\'100%\',height:\'100%\',playerVars:{playsinline:1,rel:0,origin:location.origin},events:{\n    onReady:event=>{if(generation===youtubeGeneration)event.target.playVideo();},\n    onStateChange:event=>{if(event.data===0&&generation===youtubeGeneration)window.fsjTVHome();},\n    onError:()=>{if(generation===youtubeGeneration)status(\'O YouTube não permitiu reproduzir este vídeo. Use Voltar à TV FSJ.\');}\n   }});\n  }).catch(error=>{if(generation===youtubeGeneration)status(error.message);});\n };\n function homeState(){\n  stage.classList.add(\'fsj-tv-home\');poster.hidden=false;player.hidden=true;\n  $(\'videoFullscreen\').hidden=true;$(\'institutionalEmpty\').hidden=true;$(\'projectionTitle\').textContent=\'TV FSJ\';\n  start.disabled=!library.some(video=>video.institutional);\n  start.title=start.disabled?\'Vídeo institucional ainda não cadastrado\':\'Iniciar vídeo institucional\';\n  $(\'showInstitutional\').hidden=true;\n }\n const previousProject=project;\n project=function(video){\n  clearYoutube();previousProject(video);\n  const youtubeFrame=$(\'libraryYoutubePlayer\');\n  if(video?.youtube_id&&youtubeFrame){youtubeFrame.hidden=true;youtubeFrame.removeAttribute(\'src\');}\n  if(!window.fsjWatchActive&&(!video||video.institutional))homeState();\n  else{stage.classList.remove(\'fsj-tv-home\');poster.hidden=true;$(\'showInstitutional\').hidden=false;}\n };\n function leaveFullscreen(){\n  stage.classList.remove(\'video-expanded\');\n  if(document.fullscreenElement&&stage.contains(document.fullscreenElement)||document.fullscreenElement===stage)document.exitFullscreen?.().catch(()=>{});\n  if(player.webkitDisplayingFullscreen)try{player.webkitExitFullscreen();}catch{}\n }\n window.fsjTVHome=()=>{\n  if(window.fsjWatchActive)return window.fsjWatchStop?.();\n  leaveFullscreen();$(\'videos\').value=\'\';project(library.find(video=>video.institutional));\n  status(\'TV FSJ — tela inicial.\');document.dispatchEvent(new Event(\'fsj:projection-changed\'));\n };\n start.onclick=async()=>{\n  if(window.fsjWatchActive)return status(\'Encerre a exibição em grupo antes de iniciar o institucional.\');\n  const institutional=library.find(video=>video.institutional);\n  if(!institutional)return status(\'Vídeo institucional ainda não cadastrado.\');\n  project(institutional);poster.hidden=true;stage.classList.remove(\'fsj-tv-home\');player.hidden=false;$(\'videoFullscreen\').hidden=false;$(\'showInstitutional\').hidden=false;\n  const id=institutional.id;\n  try{await player.play();if(projectedVideo?.id===id)status(\'Reproduzindo vídeo institucional.\');}\n  catch(error){if(projectedVideo?.id===id){homeState();status(\'Não foi possível iniciar o institucional. Toque em TV FSJ para tentar novamente.\');}}\n  document.dispatchEvent(new Event(\'fsj:projection-changed\'));\n };\n $(\'showInstitutional\').textContent=\'Voltar à TV FSJ\';$(\'showInstitutional\').onclick=window.fsjTVHome;\n player.addEventListener(\'play\',()=>{if(!player.paused){poster.hidden=true;stage.classList.remove(\'fsj-tv-home\');player.hidden=false;}});\n document.addEventListener(\'fsj:logout\',()=>{clearYoutube();poster.hidden=true;stage.classList.remove(\'fsj-tv-home\');});\n if(window.fsjCurrentUser&&!window.fsjWatchActive&&(!projectedVideo||projectedVideo.institutional))homeState();\n})();\n'
APPEND_CSS='/* FSJ_TV_POSTER_V1 */\n#videoStage.fsj-tv-home{display:block!important;padding-bottom:0!important}\n#fsjTVPoster{aspect-ratio:16/9;min-height:160px;max-height:32dvh;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;border:2px solid #156b42;border-radius:12px;background:linear-gradient(#bfe4ff,#e3f6d7);overflow:hidden;padding:14px}\n#fsjTVPoster[hidden],#fsjTVYoutube[hidden]{display:none!important}\n#fsjTVPoster img{display:block;width:clamp(90px,23%,190px);height:auto;max-height:17dvh;object-fit:contain}\n#content #fsjTVStart{background:#00552f;color:white;border:2px solid #edc34d;border-radius:12px;font-size:clamp(22px,4vw,36px);font-weight:bold;padding:10px 24px;margin:0;min-height:44px}\n#fsjTVStart:focus-visible{outline:3px solid #1682c6;outline-offset:3px}\n#fsjTVStart:disabled{opacity:.65;cursor:default}\n#videoStage:has(#fsjTVYoutube:not([hidden])){display:block!important}\n#fsjTVYoutube{aspect-ratio:16/9;min-height:180px;background:#000}\n#fsjTVYoutube iframe{width:100%;height:100%;min-height:180px;border:0}\n#videoStage.video-expanded #fsjTVYoutube,#videoStage:fullscreen #fsjTVYoutube{width:100%;height:100%;aspect-ratio:auto}\n@media(max-width:600px){#fsjTVPoster{gap:8px;padding:10px;max-height:29dvh}#content #fsjTVStart{font-size:24px;padding:8px 20px}}\n'

base=Path(sys.argv[1] if len(sys.argv)>1 else '/home/urbano/fsj-video-v001').resolve()
app=base/'static/app.js';style=base/'static/style.css'
if not app.is_file() or not style.is_file():raise SystemExit('Pasta do aplicativo não localizada. Nada alterado.')
text=app.read_text()
if '/* FSJ_TV_POSTER_V1 */' in text:
 print('Tela TV FSJ já instalada. Feche e reabra a aba.');sys.exit(0)
if hashlib.sha256(app.read_bytes()).hexdigest()!=EXPECTED_APP_SHA256:
 raise SystemExit('A interface mudou após a revisão. Nada alterado; envie os arquivos atuais para compatibilização.')
for old,new in REPLACEMENTS:
 if text.count(old)!=1:raise SystemExit('Trecho diferente do esperado. Nada alterado.')
 text=text.replace(old,new,1)
prepared={app:text+APPEND_JS,style:style.read_text()+'\n'+APPEND_CSS}
backup=base/'backups'/('tv-fsj-poster-'+datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f'))
backup.mkdir(parents=True)
for path in prepared:shutil.copy2(path,backup/path.name)
try:
 for path,content in prepared.items():
  temporary=path.with_name(path.name+'.tv-fsj.tmp');temporary.write_text(content);shutil.copymode(path,temporary);os.replace(temporary,path)
except Exception:
 for path in prepared:shutil.copy2(backup/path.name,path)
 raise
print('INSTALADO: TV FSJ com logotipo original e botão de início do institucional.')
print('Ao terminar o vídeo, a tela estática reaparece sem reprodução automática.')
print('Backup:',backup)
print('Feche e reabra a aba Vídeos e Chamadas. Não precisa reiniciar o servidor.')
print('Contas, autorizações, biblioteca, chamadas e rotina das 7h preservadas.')
print('Nenhum vídeo foi iniciado, enviado ou excluído pelo instalador.')
